# frozen_string_literal: true

require 'adwaita'

# VideoPlayer plays one recorded clip inline, a port of
# src/widgets/video_player.rs: a Gtk::Picture showing the decoded frames,
# wrapped in a Gtk::GraphicsOffload the way upstream wraps it, with a
# thumbnail generated by snapshotting the first frame once the stream is
# prepared. Upstream also builds a GtkMediaControls here but never parents
# it — Gallery has its own, bound to whichever slide is current — so this
# port leaves that dead field out rather than port it unused.
#
# Upstream decodes through `gtk::MediaFile`, GTK's own playback abstraction —
# backed by GStreamer on Linux, but exposed through gtk4 itself rather than
# through a separate GStreamer gem. Upstream never depends on a GstPlay
# binding either (no `gstreamer-play` crate in its Cargo.toml), which is why
# the gstreamer_play gem this port once declared had nothing to call and was
# removed from the gemspec rather than wired in here. set_file defers to the
# stream's own file= until the widget is realized, exactly as upstream's
# realize() does.
class VideoPlayer < Adwaita::Bin
  def initialize
    super()

    self.child = offload

    media_file.signal_connect('notify::playing') { update_inhibit }
  end

  def set_file(file)
    if realized?
      media_file.file = file
    else
      @pending_file = file
    end
  end

  def stream = media_file

  def pause = media_file.pause

  # Upstream's thumbnail(): a snapshot of the first frame, cached after the
  # first successful render. Returns nil rather than raising when the stream
  # has not produced a frame yet or there is no GL renderer to render with —
  # both true before the player's window has been shown.
  def thumbnail
    @thumbnail ||= snapshot_thumbnail
  end

  def realize
    super
    (surface = root&.native&.surface).then { |s| media_file.realize(s) if s }
    (pending = @pending_file).then do |file|
      if file
        @pending_file = nil
        media_file.file = file
      end
    end
  end

  private

    def update_inhibit
      window = root
      return unless window.respond_to?(:inhibit)

      if media_file.playing?
        window.inhibit('Playing Video')
      else
        window.uninhibit
      end
    end

    # Upstream's snapshot_thumbnail: the same size the gallery button and
    # camera's thumbnail button render at, letterboxed to the stream's own
    # aspect ratio.
    def snapshot_thumbnail
      size = 88.0
      t_width = media_file.intrinsic_width.to_f
      t_height = media_file.intrinsic_height.to_f
      return nil if t_width <= 0 || t_height <= 0

      ratio = t_width / t_height
      width = ratio > 1.0 ? size * ratio : size
      height = ratio > 1.0 ? size : size / ratio

      gtk_snapshot = Gtk::Snapshot.new
      media_file.snapshot(gtk_snapshot, width, height)
      node = gtk_snapshot.to_node
      return nil unless node

      renderer = native&.renderer
      renderer&.render_texture(node)
    end

    def media_file = @media_file ||= Gtk::MediaFile.new

    def picture = @picture ||= Gtk::Picture.new.tap { |pic| pic.paintable = media_file }

    def offload
      @offload ||= Gtk::GraphicsOffload.new.tap { |o| o.child = picture }
    end
end
